create extension if not exists pgcrypto; create extension if not exists pg_trgm;
create type public.app_role as enum ('student','content_creator','moderator','programme_manager','admin','super_admin');
create type public.publish_status as enum ('draft','published','archived');
create type public.moderation_status as enum ('active','pending','removed');
create or replace function public.set_updated_at() returns trigger language plpgsql security invoker set search_path='' as $$ begin new.updated_at=now(); return new; end $$;
create table public.institutions(id uuid primary key default gen_random_uuid(),name text not null,country text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(name,country));
create table public.profiles(id uuid primary key references auth.users on delete cascade,full_name text not null default '',avatar_path text,country text,city text,institution_id uuid references public.institutions,faculty text,programme text,study_level text,biography text check(char_length(biography)<=300),links jsonb not null default '{}',visibility jsonb not null default '{}',skills text[] not null default '{}',onboarding_complete boolean not null default false,deletion_requested_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.interests(id uuid primary key default gen_random_uuid(),name text not null unique,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.user_interests(user_id uuid references public.profiles on delete cascade,interest_id uuid references public.interests on delete cascade,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),primary key(user_id,interest_id));
create table public.roles(id uuid primary key default gen_random_uuid(),name public.app_role not null unique,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.user_roles(user_id uuid references public.profiles on delete cascade,role_id uuid references public.roles on delete cascade,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),primary key(user_id,role_id));
create function public.has_role(wanted public.app_role) returns boolean stable language sql security definer set search_path=public as $$select exists(select 1 from user_roles ur join roles r on r.id=ur.role_id where ur.user_id=auth.uid() and r.name=wanted)$$;
create function public.is_staff() returns boolean stable language sql security definer set search_path=public as $$select public.has_role('moderator') or public.has_role('admin') or public.has_role('super_admin')$$;
create table public.channels(id uuid primary key default gen_random_uuid(),name text not null unique,slug text not null unique,description text not null,is_active boolean not null default true,created_by uuid references public.profiles,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.posts(id uuid primary key default gen_random_uuid(),channel_id uuid not null references public.channels,author_id uuid not null references public.profiles,body text not null check(char_length(body) between 1 and 3000),is_pinned boolean not null default false,status public.moderation_status not null default 'active',deleted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.post_media(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.posts on delete cascade,storage_path text not null,mime_type text not null,byte_size int not null check(byte_size between 1 and 5242880),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.comments(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.posts on delete cascade,author_id uuid not null references public.profiles,body text not null check(char_length(body) between 1 and 1500),parent_id uuid references public.comments,status public.moderation_status not null default 'active',deleted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.reactions(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.posts on delete cascade,user_id uuid not null references public.profiles on delete cascade,kind text not null default 'like',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(post_id,user_id,kind));
create table public.resource_categories(id uuid primary key default gen_random_uuid(),name text not null unique,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.resources(id uuid primary key default gen_random_uuid(),title text not null,summary text not null,body text,resource_type text not null check(resource_type in('article','document','video','audio','external_link')),category_id uuid references public.resource_categories,author_name text not null,external_url text,storage_path text,is_restricted boolean not null default false,status public.publish_status not null default 'draft',featured boolean not null default false,published_at timestamptz,created_by uuid references public.profiles,search_vector tsvector generated always as(to_tsvector('english',title||' '||summary)) stored,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.resource_tags(id uuid primary key default gen_random_uuid(),name text not null unique,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.resource_tag_links(resource_id uuid references public.resources on delete cascade,tag_id uuid references public.resource_tags on delete cascade,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),primary key(resource_id,tag_id));
create table public.bookmarks(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles on delete cascade,post_id uuid references public.posts on delete cascade,resource_id uuid references public.resources on delete cascade,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(num_nonnulls(post_id,resource_id)=1),unique nulls not distinct(user_id,post_id,resource_id));
create table public.resource_views(id uuid primary key default gen_random_uuid(),resource_id uuid not null references public.resources on delete cascade,user_id uuid references public.profiles on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.events(id uuid primary key default gen_random_uuid(),title text not null,summary text not null,format text not null check(format in('online','physical','hybrid')),starts_at timestamptz not null,ends_at timestamptz not null,venue text,online_url text,organiser text not null,banner_path text,capacity int check(capacity>0),status public.publish_status not null default 'draft',cancelled_at timestamptz,created_by uuid references public.profiles,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(ends_at>starts_at));
create table public.event_rsvps(id uuid primary key default gen_random_uuid(),event_id uuid not null references public.events on delete cascade,user_id uuid not null references public.profiles on delete cascade,status text not null default 'going' check(status in('going','cancelled','attended','absent')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(event_id,user_id));
create table public.opportunity_categories(id uuid primary key default gen_random_uuid(),name text not null unique,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.opportunities(id uuid primary key default gen_random_uuid(),title text not null,summary text not null,category_id uuid references public.opportunity_categories,organisation text not null,eligibility text,location text not null,remote boolean not null default false,deadline timestamptz not null,application_url text not null,verified boolean not null default false,status public.publish_status not null default 'draft',created_by uuid references public.profiles,search_vector tsvector generated always as(to_tsvector('english',title||' '||summary||' '||organisation)) stored,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.opportunity_bookmarks(id uuid primary key default gen_random_uuid(),opportunity_id uuid not null references public.opportunities on delete cascade,user_id uuid not null references public.profiles on delete cascade,remind boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(opportunity_id,user_id));
create table public.content_reports(id uuid primary key default gen_random_uuid(),reporter_id uuid not null references public.profiles,post_id uuid references public.posts,comment_id uuid references public.comments,reason text not null,details text,status text not null default 'open',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(num_nonnulls(post_id,comment_id)=1));
create table public.moderation_actions(id uuid primary key default gen_random_uuid(),report_id uuid references public.content_reports,moderator_id uuid not null references public.profiles,action text not null,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles on delete cascade,title text not null,body text not null,kind text not null,target_url text,read_at timestamptz,push_attempted_at timestamptz,idempotency_key text unique,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.notification_preferences(user_id uuid primary key references public.profiles on delete cascade,comments boolean not null default true,reactions boolean not null default false,event_reminders boolean not null default true,opportunity_reminders boolean not null default true,featured_resources boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.push_tokens(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles on delete cascade,token text not null unique,platform text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.audit_logs(id uuid primary key default gen_random_uuid(),actor_id uuid references public.profiles,action text not null,entity_type text not null,entity_id uuid,metadata jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.app_settings(id uuid primary key default gen_random_uuid(),key text not null unique,value jsonb not null,updated_by uuid references public.profiles,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index posts_feed_idx on public.posts(channel_id,is_pinned desc,created_at desc) where deleted_at is null;
create index resources_publish_idx on public.resources(status,featured,published_at desc);create index resources_search_idx on public.resources using gin(search_vector);
create index events_start_idx on public.events(status,starts_at);create index opportunities_deadline_idx on public.opportunities(status,deadline);create index opportunities_search_idx on public.opportunities using gin(search_vector);
do $$declare t text;begin foreach t in array array['institutions','profiles','interests','user_interests','roles','user_roles','channels','posts','post_media','comments','reactions','bookmarks','resources','resource_categories','resource_tags','resource_tag_links','resource_views','events','event_rsvps','opportunities','opportunity_categories','opportunity_bookmarks','content_reports','moderation_actions','notifications','notification_preferences','push_tokens','audit_logs','app_settings'] loop execute format('alter table public.%I enable row level security',t); execute format('create trigger set_updated_at before update on public.%I for each row execute function public.set_updated_at()',t); end loop;end$$;

